args.command:
python3 -c "import openpyxl; wb = openpyxl.load_workbook('test - demand.xlsx'); ws = wb['WEO_Data'];
headers = ['Year', 'Real GDP Growth (%)', 'Real GDP', 'Nominal GDP', 'GDP Deflator growth (%)', 'GDP Deflator Index'];
for c, h in enumerate(headers, 1): ws.cell(1, c, h);
data = [
    [2020, -6.8, 49266.7, 49266.7, 7.2, 100.0],
    [2021, 10.5, None, 60002.8, 10.3, None],
    [2022, 10.4, None, 72265.8, 9.3, None],
    [2023, 7.8, None, 80245.3, 3.1, None],
    [2024, 7.6, None, 90543.1, 4.86, None],
    [2025, 6.0, None, None, None, None],
    [2026, 5.0, None, None, None, None],
    [2027, 5.0, None, None, None, None]
];
for r, row in enumerate(data, 2):
    for c, val in enumerate(row, 1):
        if val is not None: ws.cell(r, c, val);
# Formulas for 2021-2027
for r in range(3, 10):
    # Real GDP = Prev Real GDP * (1 + Growth)
    ws.cell(r, 3).value = f'=C{r-1}*(1+B{r}/100)';
    # GDP Deflator Index = Prev Index * (1 + Deflator Growth)
    if r <= 6: # up to 2024
        ws.cell(r, 6).value = f'=F{r-1}*(1+E{r}/100)';
    # Nominal GDP = Real GDP * Index / Base Index (100)
    ws.cell(r, 4).value = f'=C{r}*F{r}/100';

# 2025-2026 deflator growth
# For 2025, 2026, we need to estimate.
# But 2027 onwards anchor.
avg_defl_growth = '=AVERAGE(E3:E6)';
for r in range(7, 26): # 2025 to 2043 (2043 is row 25)
    ws.cell(r, 5).value = avg_defl_growth if r >= 9 else 4.0; # Assumption for 2025-2026 or just use anchor
    if r >= 9: ws.cell(r, 2).value = 5.0; # 2027-2043 growth
    if r > 2:
        if r > 6: ws.cell(r, 6).value = f'=F{r-1}*(1+E{r}/100)';
        ws.cell(r, 3).value = f'=C{r-1}*(1+B{r}/100)';
        ws.cell(r, 4).value = f'=C{r}*F{r}/100';

# Fill years until 2043
for r in range(10, 26):
    ws.cell(r, 1, 2020 + r - 2);
    ws.cell(r, 2, 5.0);
    ws.cell(r, 5).value = '=AVERAGE(E3:E6)';

wb.save('test - demand.xlsx')"

