python3 -c "import openpyxl; from openpyxl.utils import get_column_letter; wb = openpyxl.load_workbook('test - demand.xlsx'); ws = wb['NA'];
def copy_scenario(start_row, offset, multiplier=None, import_share=None):
    # Copy headers
    for r in range(1, 3):
        for c in range(2, 12):
            ws.cell(start_row + r - 1, c).value = ws.cell(r, c).value;
    # Copy years and links
    for r in range(3, 26):
        target_r = start_row + r - 1;
        ws.cell(target_r, 2).value = ws.cell(r, 2).value; # Year
        ws.cell(target_r, 3).value = f\"=VLOOKUP(B{target_r}, WEO_Data!A:F, 3, FALSE)\"; # Real GDP
        ws.cell(target_r, 4).value = ws.cell(r, 4).value; # Allocation
        ws.cell(target_r, 10).value = f\"=VLOOKUP(B{target_r}, WEO_Data!A:F, 2, FALSE)/100\"; # Baseline Growth
    # Assumptions
    ws.cell(start_row + 27, 3).value = 'Assumptions';
    ws.cell(start_row + 29, 3).value = 'total investment';
    ws.cell(start_row + 29, 4).value = 6500;
    ws.cell(start_row + 30, 3).value = 'import content share';
    ws.cell(start_row + 30, 4).value = import_share if import_share else \"='SUT Calc'!C46\";
    ws.cell(start_row + 31, 3).value = 'demand multiplier';
    ws.cell(start_row + 31, 4).value = multiplier if multiplier else 0.8;
    # Calculations
    xr = 2.746;
    inv_cell = f'$D${start_row + 29}';
    imp_cell = f'$D${start_row + 30}';
    mul_cell = f'$D${start_row + 31}';
    for r in range(start_row + 2, start_row + 25):
        ws.cell(r, 5).value = f\"={inv_cell}*D{r}*{xr}\" if ws.cell(r, 4).value else 0;
        ws.cell(r, 6).value = f\"=E{r}*{imp_cell}\";
        ws.cell(r, 7).value = f\"=(E{r}-F{r})*{mul_cell}\";
        ws.cell(r, 9).value = f\"=G{r}/C{r}\";
        ws.cell(r, 11).value = f\"=J{r}+I{r}\";

copy_scenario(45, 44, multiplier=1.0); # Scenario 2
copy_scenario(89, 88, import_share=0.5); # Scenario 3
wb.save('test - demand.xlsx')"

